insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('utterance-of-marvels-i','MAIN','PROLOGUE · ACT I','{"en":"Utterance of Marvels: I","id":"Ucapan Keajaiban: I"}'::jsonb,null,null,null,'1.0','1.X','Huanglong',array['Rover','Yangyang','Chixia']::text[],null,'2024-05-23','{"en":"The Rover wakes with no memory in a strange world, and a sudden battle reveals the power to absorb Echoes.","id":"Sang Rover terbangun tanpa ingatan di dunia yang asing, dan sebuah pertarungan mendadak menyingkap kekuatan untuk menyerap Echo."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Strangers who seem to know the Rover greet them in a hazy wilderness. When a powerful enemy appears, the Rover discovers they can absorb the Echoes of defeated Tacet Discords, a gift that sets the whole journey in motion."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Orang-orang asing yang seolah mengenal sang Rover menyambutnya di alam liar yang berkabut. Saat musuh kuat muncul, Rover mendapati dirinya mampu menyerap Echo dari Tacet Discord yang dikalahkan, anugerah yang memulai seluruh perjalanan."}]}]}}'::jsonb,100,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/454537') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('utterance-of-marvels-ii','MAIN','PROLOGUE · ACT II','{"en":"Utterance of Marvels: II","id":"Ucapan Keajaiban: II"}'::jsonb,null,null,null,'1.0','1.X','Huanglong',array['Rover','Yangyang','Chixia']::text[],null,'2024-05-23','{"en":"Leaving the Gorges of Spirits, the Rover learns to use Echoes and heads for Jinzhou, the heart of Huanglong.","id":"Meninggalkan Gorges of Spirits, Rover belajar menggunakan Echo dan menuju Jinzhou, jantung Huanglong."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rover absorbs their first Echo from a fallen Tacet Discord and grows stronger with each fight. The road ends at the gates of Jinzhou, the bright capital of Huanglong."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rover menyerap Echo pertamanya dari Tacet Discord yang tumbang dan bertambah kuat di setiap pertarungan. Perjalanan berakhir di gerbang Jinzhou, ibu kota Huanglong yang gemerlap."}]}]}}'::jsonb,200,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/454703') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('first-resonance','MAIN','CH. I · ACT I','{"en":"First Resonance","id":"Resonansi Pertama"}'::jsonb,null,null,null,'1.0','1.X','Jinzhou',array['Rover','Sanhua','Jinhsi']::text[],null,'2024-05-23','{"en":"Invited by Jinzhou''s Magistrate, the Rover instead finds a trail of tokens hinting at where she has gone.","id":"Diundang oleh Magistrat Jinzhou, Rover justru menemukan jejak tanda yang mengisyaratkan ke mana ia pergi."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rover arrives in Jinzhou expecting an audience with the Magistrate, but she is absent. In her place are tokens and riddles, the first steps of a search across Huanglong."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rover tiba di Jinzhou dan berharap bertemu sang Magistrat, tetapi ia tidak ada. Sebagai gantinya ada tanda dan teka-teki, langkah pertama sebuah pencarian di seluruh Huanglong."}]}]}}'::jsonb,300,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/454733') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('echoing-marche','MAIN','CH. I · ACT II','{"en":"Echoing Marche","id":"Mars yang Bergema"}'::jsonb,null,null,null,'1.0','1.X','Huanglong',array['Rover','Jiyan']::text[],null,'2024-05-23','{"en":"The Magistrate''s trail leads to the front line of Huanglong''s war against the Tacet Discords.","id":"Jejak sang Magistrat mengarah ke garis depan perang Huanglong melawan Tacet Discord."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Following the second token, the Rover reaches a region gripped by fear of the Tacet Discords. There a general leads the defence from the front, and the Rover joins the fight."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Mengikuti tanda kedua, Rover tiba di wilayah yang dicekam ketakutan akan Tacet Discord. Di sana seorang jenderal memimpin pertahanan dari garis depan, dan Rover ikut bertempur."}]}]}}'::jsonb,400,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/454745') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('ominous-star','MAIN','CH. I · ACT III','{"en":"Ominous Star","id":"Bintang Pertanda Buruk"}'::jsonb,null,null,null,'1.0','1.X','Qichi Village',array['Rover','Scar']::text[],null,'2024-05-23','{"en":"Clues lead to the ruined Qichi Village, where the one who destroyed it is waiting.","id":"Petunjuk membawa Rover ke reruntuhan Desa Qichi, tempat sang penghancurnya menunggu."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The next clue points to Qichi Village, a place emptied by tragedy. Among the ruins the Rover meets the figure responsible for its fall."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Petunjuk berikutnya mengarah ke Desa Qichi, tempat yang dikosongkan oleh tragedi. Di antara reruntuhan, Rover bertemu sosok yang bertanggung jawab atas kehancurannya."}]}]}}'::jsonb,500,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/455004') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('clashing-blades','MAIN','CH. I · ACT IV','{"en":"Clashing Blades","id":"Benturan Pedang"}'::jsonb,null,null,null,'1.0','1.X','Jinzhou',array['Rover','Jinhsi','Scar']::text[],null,'2024-05-23','{"en":"In Jinzhou''s hidden Grand Library the Rover finally meets the Magistrate, as an old enemy walks into a trap.","id":"Di Perpustakaan Agung Jinzhou yang tersembunyi, Rover akhirnya bertemu sang Magistrat, saat musuh lama masuk ke dalam perangkap."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With every token solved, the Rover is led into the Grand Library for the long-awaited meeting. Just as answers come close, a familiar foe returns and the Magistrate''s plan to seal him away springs shut."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah semua tanda terpecahkan, Rover dibawa ke Perpustakaan Agung untuk pertemuan yang lama dinanti. Tepat saat jawaban mendekat, musuh lama kembali dan rencana sang Magistrat untuk menyegelnya pun dijalankan."}]}]}}'::jsonb,600,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/455883') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('rewinding-raindrops','MAIN','CH. I · ACT V','{"en":"Rewinding Raindrops","id":"Tetes Hujan yang Berbalik"}'::jsonb,null,null,null,'1.0','1.X','Huanglong',array['Rover','Jinhsi','Yangyang']::text[],null,'2024-05-23','{"en":"Rain falls upward as a Threnodian stirs, and the Rover sets out to find the elusive Black Shores.","id":"Hujan jatuh ke atas saat seekor Threnodian bergerak, dan Rover berangkat mencari Black Shores yang misterius."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A message from the Sentinel sends the Rover looking for the Black Shores. Meanwhile Retrograde Rain climbs into the sky, a sign that a Threnodian is waking and that a catastrophe may follow."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pesan dari sang Sentinel membuat Rover mencari Black Shores. Sementara itu Hujan Retrograd naik ke langit, tanda bahwa seekor Threnodian terbangun dan bencana bisa menyusul."}]}]}}'::jsonb,700,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/456178') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('grand-warstorm','MAIN','CH. I · ACT VI','{"en":"Grand Warstorm","id":"Badai Perang Besar"}'::jsonb,null,null,null,'1.0','1.X','Huanglong',array['Rover','Jinhsi','Jiyan']::text[],null,'2024-05-23','{"en":"Huanglong goes to war against a flood of Tacet Discords as the Rover faces the Threnodian, the Dreamless.","id":"Huanglong berperang melawan gelombang Tacet Discord saat Rover menghadapi sang Threnodian, Dreamless."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tacet Discords pour across Huanglong and the nation commits everything to its defence. At the centre of the storm the Rover confronts the Dreamless to stop the threat to the whole nation."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Tacet Discord membanjiri Huanglong dan bangsa itu mengerahkan segalanya untuk bertahan. Di pusat badai, Rover menghadapi Dreamless untuk menghentikan ancaman bagi seluruh negeri."}]}]}}'::jsonb,800,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/456226') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
