insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('thaw-of-eons','MAIN','CH. I · ACT VII','{"en":"Thaw of Eons","id":"Mencairnya Zaman"}'::jsonb,null,null,null,'1.1','1.X','Mt. Firmament',array['Rover','Jinhsi','Changli','Abby']::text[],null,'2024-06-28','{"en":"With the Sentinel missing, the Rover travels to Mt. Firmament, where time itself has stopped flowing normally.","id":"Dengan hilangnya sang Sentinel, Rover pergi ke Mt. Firmament, tempat waktu tak lagi mengalir semestinya."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After the Threnodian falls, the Rover gains a new companion and follows dreams of Sentinel Jue to Mt. Firmament. Time there has warped, and freeing the captive Sentinel forces the Magistrate to defy destiny for her city."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah sang Threnodian tumbang, Rover mendapat pendamping baru dan mengikuti mimpi tentang Sentinel Jue ke Mt. Firmament. Waktu di sana telah menyimpang, dan membebaskan sang Sentinel yang terkurung memaksa sang Magistrat menentang takdir demi kotanya."}]}]}}'::jsonb,1600,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/459842') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
