insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('through-the-sea-thou-break','MAIN','CH. II · PROLOGUE','{"en":"Through the Sea Thou Break","id":"Menembus Lautan"}'::jsonb,null,null,null,'2.0','2.X','Rinascita',array['Rover','Abby']::text[],null,'2025-01-02','{"en":"To save Abby''s fading frequency, the Rover sails for Ragunna in search of Imperator, Sentinel of Rinascita.","id":"Demi menyelamatkan frekuensi Abby yang memudar, Rover berlayar ke Ragunna mencari Imperator, Sentinel Rinascita."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Abby''s frequency is weakening and only Rinascita''s Sentinel may hold the cure. The Rover crosses uncharted waters toward Ragunna, where long-hidden answers wait."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Frekuensi Abby melemah dan hanya Sentinel Rinascita yang mungkin punya penawarnya. Rover menyeberangi perairan yang belum terpetakan menuju Ragunna, tempat jawaban yang lama tersembunyi menunggu."}]}]}}'::jsonb,2300,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/492480') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('the-sacred-breeze-so-often-breathes','MAIN','CH. II · ACT I','{"en":"The Sacred Breeze So Often Breathes","id":"Angin Suci yang Selalu Berembus"}'::jsonb,null,null,null,'2.0','2.X','Ragunna',array['Rover','Carlotta']::text[],null,'2025-01-02','{"en":"A friendly member of a great Rinascitan family guides the Rover through Ragunna, where something uncanny lurks.","id":"Anggota ramah dari keluarga besar Rinascita memandu Rover menjelajahi Ragunna, tempat sesuatu yang ganjil bersembunyi."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rover is welcomed into Ragunna''s lively streets by one of the city''s leading families. Beneath the colour and music, signs appear that something is wrong with the city."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rover disambut di jalanan Ragunna yang ramai oleh salah satu keluarga terkemuka kota itu. Di balik warna dan musik, muncul tanda bahwa ada yang tidak beres dengan kota itu."}]}]}}'::jsonb,2400,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/492487') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('veils-off-in-sun-or-shadow','MAIN','CH. II · ACT II','{"en":"Veils Off in Sun or Shadow","id":"Tabir Tersingkap di Terang maupun Bayang"}'::jsonb,null,null,null,'2.0','2.X','Ragunna',array['Rover','Carlotta','Roccia']::text[],null,'2025-01-02','{"en":"Strange events follow a member of the Fisalia family, and the Rover joins an investigation to find out why.","id":"Peristiwa aneh mengikuti seorang anggota keluarga Fisalia, dan Rover ikut menyelidiki penyebabnya."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Montelli family and an Acolyte of the Order team up with the Rover to look into a Fisalia family member whose arrival brought strange occurrences to Ragunna."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keluarga Montelli dan seorang Akolit Ordo bekerja sama dengan Rover untuk menyelidiki anggota keluarga Fisalia yang kedatangannya membawa kejadian aneh ke Ragunna."}]}]}}'::jsonb,2500,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/492483') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
