insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('flames-of-heart','MAIN','CH. II · ACT VI','{"en":"Flames of Heart","id":"Api di Dalam Hati"}'::jsonb,null,null,null,'2.4','2.X','Septimont',array['Rover','Lupa']::text[],null,'2025-07-03','{"en":"As Septimont''s anomaly unravels, the Rover and Lupa hunt the mastermind behind it.","id":"Saat anomali Septimont terungkap, Rover dan Lupa memburu dalang di baliknya."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rover and the star gladiator Lupa follow the trail into a burial ground of heroes. Lupa''s burning resolve proves she belongs at the centre of the city''s story."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rover dan gladiator bintang Lupa mengikuti jejak hingga ke pemakaman para pahlawan. Tekad Lupa yang membara membuktikan bahwa ia layak menjadi pusat kisah kota itu."}]}]}}'::jsonb,3600,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/533154') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('dreamcatchers-in-the-secret-gardens','MAIN','CH. II · ACT VII','{"en":"Dreamcatchers in the Secret Gardens","id":"Penangkap Mimpi di Taman Rahasia"}'::jsonb,null,null,null,'2.5','2.X','Rinascita',array['Rover','Phrolova']::text[],null,'2025-07-24','{"en":"A dreamer seals her heart away in a hidden realm of dreams built on melancholy music.","id":"Seorang pemimpi mengunci hatinya di dunia mimpi tersembunyi yang dibangun dari musik melankolis."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rover follows a dreamer into a realm beyond ordinary sight, shaped by sorrowful melodies. She walks a fragile path between hope and delusion and refuses to look back."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rover mengikuti seorang pemimpi ke alam di luar pandangan biasa, yang dibentuk oleh melodi yang sendu. Ia menempuh jalan rapuh antara harapan dan khayalan dan menolak menoleh ke belakang."}]}]}}'::jsonb,3700,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/538764') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('overture-rust-sword-and-the-sun','SEGUE','CH. II · OVERTURE','{"en":"Overture: Rust, Sword, and the Sun","id":"Overtur: Karat, Pedang, dan Matahari"}'::jsonb,null,null,null,'2.6','2.X','Septimont',array['Rover','Abby','Augusta']::text[],null,'2025-08-28','{"en":"A mysterious figure retells the story of Augusta before she became Septimont''s leader.","id":"Sosok misterius menceritakan kembali kisah Augusta sebelum ia menjadi pemimpin Septimont."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"While checking on Septimont after recent events, the Rover and Abby meet a stranger who wants to tell Augusta''s story from before she rose to lead the nation."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Saat memeriksa keadaan Septimont setelah peristiwa terakhir, Rover dan Abby bertemu orang asing yang ingin menceritakan kisah Augusta sebelum ia memimpin bangsanya."}]}]}}'::jsonb,3800,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/543756') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('by-sun-s-burning-hand','MAIN','CH. II · ACT VIII','{"en":"By Sun''s Burning Hand","id":"Oleh Tangan Matahari yang Membara"}'::jsonb,null,null,null,'2.6','2.X','Sanguis Plateau',array['Rover','Augusta','Iuno']::text[],null,'2025-08-28','{"en":"The Ephor Augusta invites the Rover to the Hunt on the Sanguis Plateau, where the Dark Tide never recedes.","id":"Sang Ephor Augusta mengundang Rover ke Perburuan di Dataran Sanguis, tempat Pasang Gelap tak pernah surut."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"On the ominous plateau the Rover joins Septimont''s Hunt against the Dark Tide. The journey uncovers a prophecy that binds the Ephor to the Priestess Iuno."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Di dataran yang muram itu, Rover ikut dalam Perburuan Septimont melawan Pasang Gelap. Perjalanan ini menyingkap sebuah ramalan yang mengikat sang Ephor dengan Pendeta Iuno."}]}]}}'::jsonb,3900,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/545730') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('by-moon-s-fated-light','MAIN','CH. II · ACT IX','{"en":"By Moon''s Fated Light","id":"Oleh Cahaya Bulan yang Ditakdirkan"}'::jsonb,null,null,null,'2.6','2.X','Sanguis Plateau',array['Rover','Iuno','Augusta']::text[],null,'2025-08-28','{"en":"The Dark Tide retreats, but the Priestess Iuno vanishes from the world and from everyone''s memory.","id":"Pasang Gelap mundur, tetapi Pendeta Iuno lenyap dari dunia dan dari ingatan semua orang."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Septimont celebrates pushing back the Dark Tide, yet Iuno is gone and almost no one remembers her. The Rover investigates her disappearance and tries to pull her back from Chaos."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Septimont merayakan keberhasilan memukul mundur Pasang Gelap, namun Iuno hilang dan hampir tak ada yang mengingatnya. Rover menyelidiki hilangnya dia dan berusaha menariknya kembali dari Kekacauan."}]}]}}'::jsonb,4000,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/545731') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('the-bygone-shall-always-return','MAIN','CH. II · ACT X','{"en":"The Bygone Shall Always Return","id":"Yang Telah Berlalu Akan Selalu Kembali"}'::jsonb,null,null,null,'2.7','2.X','Rinascita',array['Rover','Galbrena','Iuno']::text[],null,'2025-10-09','{"en":"A winged figure who seems to command Tacet Discords challenges the Rover: who is Galbrena?","id":"Sosok bersayap api yang seolah memerintah Tacet Discord menantang Rover: siapakah Galbrena?"}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With Iuno rescued, a new mystery appears in the form of Galbrena, who flies on wings of fire. The Rover sets out to learn who she is and what she wants."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah Iuno diselamatkan, misteri baru muncul dalam wujud Galbrena yang terbang dengan sayap api. Rover berangkat untuk mengetahui siapa dia dan apa tujuannya."}]}]}}'::jsonb,4100,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/555987') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('dawn-breaks-on-dark-tides','MAIN','CH. II · ACT XI','{"en":"Dawn Breaks on Dark Tides","id":"Fajar Menyingsing di Atas Pasang Gelap"}'::jsonb,null,null,null,'2.7','2.X','Rinascita',array['Rover','Cartethyia','Augusta','Galbrena']::text[],null,'2025-10-09','{"en":"All of Rinascita hangs in the balance as the Threnodian Leviathan prepares to return.","id":"Seluruh Rinascita dipertaruhkan saat Threnodian Leviathan bersiap untuk kembali."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Every thread of the chapter leads here. The Rover and their allies stand against the returning Leviathan in the final battle for Rinascita."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setiap benang kisah bab ini bermuara di sini. Rover dan sekutunya menghadapi Leviathan yang kembali dalam pertempuran terakhir demi Rinascita."}]}]}}'::jsonb,4200,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/556087') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('stranger-in-a-strange-land','SEGUE','CH. II · AFTERSTORY','{"en":"Stranger in a Strange Land","id":"Orang Asing di Negeri Asing"}'::jsonb,null,null,null,'2.7','2.X','Rinascita',array['Qiuyuan']::text[],null,'2025-10-09','{"en":"The blind swordsman Qiuyuan retells recent events in Rinascita from his own point of view.","id":"Pendekar pedang buta Qiuyuan menceritakan kembali peristiwa terbaru di Rinascita dari sudut pandangnya."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With the Rinascita chapter closed, the story steps aside to follow Qiuyuan. His path through the same events reveals new stories and secrets."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah bab Rinascita ditutup, cerita beralih mengikuti Qiuyuan. Perjalanannya melalui peristiwa yang sama menyingkap kisah dan rahasia baru."}]}]}}'::jsonb,4300,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/556238') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('stagnant-dawn-on-wastelands','MAIN','CH. II · ACT XII','{"en":"Stagnant Dawn on Wastelands","id":"Fajar yang Terhenti di Tanah Gersang"}'::jsonb,null,null,null,'2.8','2.X','Honami City',array['Rover','Chisa']::text[],null,'2025-11-20','{"en":"Shifting coordinates from the Threnodian''s Gem lead the Rover to a metropolis that was erased long ago.","id":"Koordinat yang terus bergeser dari Permata Threnodian membawa Rover ke sebuah metropolis yang telah lama terhapus."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"While the Black Shores study the Leviathan''s Gem, a pair of drifting coordinates points somewhere unknown. Following them, the Rover arrives in a city that should no longer exist."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Saat Black Shores meneliti Permata sang Leviathan, sepasang koordinat yang terus bergeser menunjuk ke tempat tak dikenal. Mengikutinya, Rover tiba di sebuah kota yang seharusnya sudah tidak ada."}]}]}}'::jsonb,4400,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/564916') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('flowing-starlight-in-the-iris','SEGUE','CH. II · SEGUE','{"en":"Flowing Starlight in the Iris","id":"Cahaya Bintang yang Mengalir di Iris"}'::jsonb,null,null,null,'2.8','2.X','Black Shores',array['Rover','Chisa']::text[],null,'2025-11-20','{"en":"After escaping Honami City, the Rover visits Chisa as she recovers at the Black Shores.","id":"Setelah lolos dari Kota Honami, Rover menjenguk Chisa yang sedang pulih di Black Shores."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chisa pushed herself to the edge of overclocking more than once during the escape. Now she is being treated at the Black Shores, and the reunion becomes a new beginning for both of them."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Chisa berkali-kali memaksa dirinya hingga ambang overclocking selama pelarian. Kini ia dirawat di Black Shores, dan pertemuan kembali itu menjadi awal baru bagi keduanya."}]}]}}'::jsonb,4500,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/564931') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('when-the-unknown-thrums','MAIN','CH. III · PROLOGUE','{"en":"When the Unknown Thrums","id":"Saat yang Tak Dikenal Berdengung"}'::jsonb,null,null,null,'3.0','3.X','Lahai-Roi',array['Rover','Chisa']::text[],null,'2025-12-25','{"en":"Through a stabilised portal, the Rover and Chisa arrive at Startorch Academy and straight into a Voidstorm.","id":"Melalui portal yang telah stabil, Rover dan Chisa tiba di Akademi Startorch dan langsung menghadapi Voidstorm."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rover and Chisa head to Startorch Academy in Lahai-Roi. On arrival they face another attempt to steal the Rover''s frequency and a Voidstorm sweeping over the campus."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rover dan Chisa menuju Akademi Startorch di Lahai-Roi. Begitu tiba, mereka menghadapi upaya lain untuk mencuri frekuensi Rover dan Voidstorm yang menyapu kampus."}]}]}}'::jsonb,4600,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/571778') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('what-burns-beneath-frostlands','MAIN','CH. III · ACT I','{"en":"What Burns Beneath Frostlands","id":"Yang Membara di Bawah Tanah Beku"}'::jsonb,null,null,null,'3.0','3.X','Lahai-Roi',array['Rover','Lynae']::text[],null,'2025-12-25','{"en":"Lynae welcomes the new student to Startorch Academy with a campus tour that hides its own agenda.","id":"Lynae menyambut murid baru di Akademi Startorch dengan tur kampus yang menyimpan agenda tersendiri."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After rescuing the Rover from a Voidworm attack, Lynae offers an impromptu tour of Lahai-Roi. Her friendly welcome comes with a purpose she has not yet revealed."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah menyelamatkan Rover dari serangan Voidworm, Lynae menawarkan tur dadakan keliling Lahai-Roi. Sambutan hangatnya membawa tujuan yang belum ia ungkapkan."}]}]}}'::jsonb,4700,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/571785') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('ode-to-the-second-sunrise','MAIN','CH. III · ACT II','{"en":"Ode to the Second Sunrise","id":"Pujian bagi Matahari Terbit Kedua"}'::jsonb,null,null,null,'3.0','3.X','Lahai-Roi',array['Rover','Mornye']::text[],null,'2025-12-25','{"en":"The Rover and Professor Mornye race to stop Lahai-Roi''s artificial sun from crashing into the underground.","id":"Rover dan Profesor Mornye berpacu mencegah matahari buatan Lahai-Roi jatuh ke dunia bawah tanah."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Outside Fractsidus agents plan to disrupt the New Solar Ceremony. The Rover teams up with Professor Mornye to keep the artificial sun in the sky."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Agen Fractsidus dari luar berencana mengacaukan Upacara Surya Baru. Rover bekerja sama dengan Profesor Mornye agar matahari buatan tetap di langit."}]}]}}'::jsonb,4800,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/571796') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
