insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('the-star-that-voyages-far','MAIN','CH. III · ACT III','{"en":"The Star That Voyages Far","id":"Bintang yang Berlayar Jauh"}'::jsonb,null,null,null,'3.1','3.X','Frostlands Surface',array['Rover','Aemeath','Luuk Herssen']::text[],null,'2026-02-05','{"en":"The Rover meets Aemeath and, with Luuk Herssen, discovers an orbital station holding truths about Solaris-3''s future.","id":"Rover bertemu Aemeath dan bersama Luuk Herssen menemukan stasiun orbit yang menyimpan kebenaran tentang masa depan Solaris-3."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Aemeath''s unusual circumstances draw the Rover into a journey to the Frostlands Surface with Luuk Herssen. An orbital space station reveals major findings about Solaris-3, the Rover''s origins and Aemeath''s true goal with the Exostrider."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Keadaan Aemeath yang tidak biasa menarik Rover ke dalam perjalanan menuju Permukaan Frostlands bersama Luuk Herssen. Sebuah stasiun luar angkasa di orbit mengungkap temuan besar tentang Solaris-3, asal-usul Rover, dan tujuan sejati Aemeath dengan Exostrider."}]}]}}'::jsonb,5000,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/578306') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('all-that-sunlight-touches','SEGUE','CH. III · SEGUE','{"en":"All That Sunlight Touches","id":"Segala yang Disentuh Cahaya Matahari"}'::jsonb,null,null,null,'3.1','3.X','Roya Frostlands',array['Rover','Luuk Herssen']::text[],null,'2026-02-05','{"en":"The Rover and Luuk Herssen regroup, then return to the orbital station when Nivora is taken there.","id":"Rover dan Luuk Herssen menyusun ulang strategi, lalu kembali ke stasiun orbit saat Nivora dibawa ke sana."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After a painful turn of events in Roya Frostlands, the two plan their next move. A kidnapping forces them back to the orbital space station."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah rangkaian peristiwa yang menyakitkan di Roya Frostlands, keduanya merencanakan langkah berikutnya. Sebuah penculikan memaksa mereka kembali ke stasiun luar angkasa di orbit."}]}]}}'::jsonb,5100,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/578309') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('gold-suspended-in-the-shadows','MAIN','CH. III · ACT IV','{"en":"Gold Suspended in the Shadows","id":"Emas yang Menggantung di Dalam Bayang"}'::jsonb,null,null,null,'3.2','3.X','Startorch Academy',array['Rover','Sigrika']::text[],null,'2026-03-19','{"en":"Hunting an infiltrator inside the academy, the Rover is drawn into quests with Sigrika, heir of the Heliodic Six.","id":"Saat memburu penyusup di dalam akademi, Rover terlibat dalam misi bersama Sigrika, penerus Heliodic Six."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rover searches Startorch Academy for a possible infiltrator. Along the way they become caught up in a series of tasks with Sigrika, successor to Roya''s Heliodic Six, during the New Solar Celebration."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rover mencari kemungkinan penyusup di Akademi Startorch. Di tengah jalan, mereka terlibat serangkaian tugas bersama Sigrika, penerus Heliodic Six dari Roya, selama Perayaan Surya Baru."}]}]}}'::jsonb,5200,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/586746') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
