insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('starlights-from-yesterdays','MAIN','CH. III · ACT V','{"en":"Starlights from Yesterdays","id":"Cahaya Bintang dari Hari-Hari Kemarin"}'::jsonb,null,null,null,'3.3','3.X','Lahai-Roi',array['Rover','Aemeath','Lynae','Luuk Herssen']::text[],null,'2026-04-30','{"en":"Solaris faces Aleph-1 across space and time to save Aemeath and break the world''s devastating loop.","id":"Solaris menghadapi Aleph-1 melintasi ruang dan waktu demi menyelamatkan Aemeath dan memutus siklus yang menghancurkan dunia."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Prepared for the world-ending threat of Aleph-1, the Rover and their allies fight the Threnodian across space and time. Their goal is to save Aemeath and the Exostrider and end the loop the world is trapped in."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Siap menghadapi ancaman kiamat Aleph-1, Rover dan sekutunya melawan sang Threnodian melintasi ruang dan waktu. Tujuan mereka adalah menyelamatkan Aemeath dan Exostrider serta mengakhiri siklus yang menjerat dunia."}]}]}}'::jsonb,5500,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/597003') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('beneath-a-melting-night-sky','SEGUE','CH. III · SEGUE','{"en":"Beneath a Melting Night Sky","id":"Di Bawah Langit Malam yang Mencair"}'::jsonb,null,null,null,'3.3','3.X','Lahai-Roi',array['Rover','Denia']::text[],null,'2026-04-30','{"en":"After victory over Aleph-1, the Rover looks for the Artificial Resonator Denia and her origins.","id":"Setelah kemenangan atas Aleph-1, Rover mencari Resonator Buatan Denia dan asal-usulnya."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With the Fractsidus and Aleph-1 defeated, the Rover tracks down Denia to learn where she came from and what she is facing now."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah Fractsidus dan Aleph-1 dikalahkan, Rover melacak Denia untuk mengetahui asal-usulnya dan apa yang sedang ia hadapi."}]}]}}'::jsonb,5600,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/597023') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('at-dream-s-edge','EVNT','CH. III · SIDE STORY','{"en":"At Dream''s Edge","id":"Di Tepi Mimpi"}'::jsonb,null,null,null,'3.4','3.X','Lahai-Roi',array['Rover']::text[],null,'2026-06-08','{"en":"A collaboration side story in which the Rover faces an otherworldly enemy alongside otherworldly friends.","id":"Cerita sampingan kolaborasi saat Rover menghadapi musuh dari dunia lain bersama kawan-kawan dari dunia lain."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Part of the Cyberpunk: Edgerunners collaboration and separate from the main plot. The Rover meets an unlikely enemy from another world and unexpected allies who are ready to help."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Bagian dari kolaborasi Cyberpunk: Edgerunners dan terpisah dari alur utama. Rover bertemu musuh tak terduga dari dunia lain dan sekutu tak terduga yang siap membantu."}]}]}}'::jsonb,5700,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/603079') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('we-choose-the-sky','SEGUE','CH. III · SEGUE','{"en":"We Choose the Sky","id":"Kami Memilih Langit"}'::jsonb,null,null,null,'3.4','3.X','Startorch Academy',array['Lucilla','Rover']::text[],null,'2026-06-08','{"en":"Lucilla takes centre stage again as she weighs the future threats facing Startorch Academy and Lahai-Roi.","id":"Lucilla kembali menjadi sorotan saat ia menimbang ancaman masa depan bagi Akademi Startorch dan Lahai-Roi."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"After the Fractsidus attack and the banishing of Aleph-1, Lucilla turns to what comes next for the academy and for Lahai-Roi."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah serangan Fractsidus dan terusirnya Aleph-1, Lucilla memikirkan apa yang akan datang bagi akademi dan Lahai-Roi."}]}]}}'::jsonb,5800,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/603081') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('the-wind-before-the-storm','MAIN','CH. IV · ACT I','{"en":"The Wind Before the Storm","id":"Angin Sebelum Badai"}'::jsonb,null,null,null,'3.5','3.X','Mengzhou',array['Rover','Suisui','Yangyang']::text[],null,'2026-07-10','{"en":"Back in Huanglong, the Rover learns Yangyang is missing in Xuanfang and joins her sister Suisui to find her.","id":"Kembali ke Huanglong, Rover mengetahui Yangyang hilang di Xuanfang dan bergabung dengan adiknya, Suisui, untuk mencarinya."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"With Lahai-Roi safe, the Rover returns to Huanglong to look into their origins and the next Threnodian threat. On the way they hear that an expedition into Xuanfang went wrong and Yangyang has vanished."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Setelah Lahai-Roi aman, Rover kembali ke Huanglong untuk menelusuri asal-usulnya dan ancaman Threnodian berikutnya. Di perjalanan, mereka mendengar ekspedisi ke Xuanfang gagal dan Yangyang menghilang."}]}]}}'::jsonb,5900,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/606975') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('xuanling-sings-storm-quelled','MAIN','CH. IV · ACT II','{"en":"Xuanling Sings, Storm Quelled","id":"Xuanling Bernyanyi, Badai Mereda"}'::jsonb,null,null,null,'3.5','3.X','Xuanfang Hold',array['Rover','Suisui','Yangyang']::text[],null,'2026-07-10','{"en":"Rogue Autopuppets riot through Xuanfang, and an artisan chasing Sentinel technology launches a full assault.","id":"Autopuppet liar mengamuk di Xuanfang, dan seorang artisan yang memburu teknologi Sentinel melancarkan serangan besar."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"The Rover and Suisui find that a troubled artisan is behind the rogue Autopuppets. When the artisan turns them on Xuanfang Hold, the Rover and their allies must defend it."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Rover dan Suisui menemukan bahwa seorang artisan yang bermasalah berada di balik Autopuppet liar. Saat ia mengarahkan mereka ke Benteng Xuanfang, Rover dan sekutunya harus mempertahankannya."}]}]}}'::jsonb,6000,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/606977') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('the-chant-of-unseen-tides','SEGUE','CH. IV · SEGUE','{"en":"The Chant of Unseen Tides","id":"Kidung Pasang yang Tak Terlihat"}'::jsonb,null,null,null,'3.5','3.X','Xuanfang Hold',array['Yangyang']::text[],null,'2026-07-10','{"en":"Helping Xuanfang recover, Yangyang begins to hear whispering voices inside her head.","id":"Saat membantu Xuanfang pulih, Yangyang mulai mendengar suara-suara berbisik di dalam kepalanya."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yangyang stays to help citizens affected by the attack while waiting for her Resonance Report. Murmuring voices follow her, and she sets out to find their source."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Yangyang tetap tinggal untuk membantu warga yang terdampak serangan sambil menunggu Laporan Resonansinya. Suara-suara bergumam mengikutinya, dan ia berusaha menemukan sumbernya."}]}]}}'::jsonb,6100,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/606978') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
