insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('song-of-the-heart-sword','MAIN','CH. IV · ACT III','{"en":"Song of the Heart Sword","id":"Lagu Pedang Hati"}'::jsonb,null,null,null,'3.6','3.X','Xuanfang Hold',array['Rover','Qingxiao','Jingran','Yangyang']::text[],null,'2026-08-20','{"en":"Searching for Hsin with Qingxiao, the Rover is pulled into a war among cloud shuttles above Xuanfang.","id":"Mencari Hsin bersama Qingxiao, Rover terseret ke dalam perang di antara kapal awan di atas Xuanfang."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Xianling Village comes under attack and a strange coin pendant opens a path into the Manifold Sanctum. The Rover and the sword master Qingxiao cross fleets of Cloud Shuttles, face her past, and stand against Muyu."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Desa Xianling diserang dan sebuah liontin koin aneh membuka jalan ke Manifold Sanctum. Rover dan ahli pedang Qingxiao menyeberangi armada Kapal Awan, menghadapi masa lalunya, dan melawan Muyu."}]}]}}'::jsonb,6300,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/614751') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('the-nethermancer-s-requiem','SEGUE','CH. IV · SEGUE','{"en":"The Nethermancer''s Requiem","id":"Requiem Sang Nethermancer"}'::jsonb,null,null,null,'3.6','3.X','Xuanfang Hold',array['Jingran']::text[],null,'2026-08-20','{"en":"A segue centred on Jingran, the Nethermancer, set after the battle above Xuanfang.","id":"Selingan yang berpusat pada Jingran, sang Nethermancer, setelah pertempuran di atas Xuanfang."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"This segue continues the story of Jingran after the events of Song of the Heart Sword and leads into Act IV."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Selingan ini melanjutkan kisah Jingran setelah peristiwa Lagu Pedang Hati dan mengantar ke Babak IV."}]}]}}'::jsonb,6400,'published',null,true,'https://game8.co/games/Wuthering-Waves/archives/614756') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('simulacrum-of-the-heart','MAIN','CH. IV · ACT IV','{"en":"Simulacrum of the Heart","id":"Simulakrum Hati"}'::jsonb,null,null,null,'3.7','3.X','Mengzhou',array['Rover','Hsin','Suoming','Qingxiao']::text[],null,'2026-09-30','{"en":"Rumours say Xuanfang Hold is near collapse, and the Rover enters Hsin''s Heart Realm to find the fading Moon Fox.","id":"Kabar beredar bahwa Benteng Xuanfang hampir runtuh, dan Rover memasuki Alam Hati Hsin untuk menemukan Rubah Bulan yang memudar."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Qingxiao fears Hsin''s presence is weakening, so the Rover follows Intendant Suoming into the Manifold Sanctum. In the Simulacrum Nexus and Hsin''s memories they uncover what happened to the Moon Fox before the Waking Moon Festival."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Qingxiao khawatir kehadiran Hsin melemah, maka Rover mengikuti Intendan Suoming ke Manifold Sanctum. Di Simulacrum Nexus dan ingatan Hsin, mereka mengungkap apa yang terjadi pada sang Rubah Bulan sebelum Festival Bulan Terjaga."}]}]}}'::jsonb,6500,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/624354') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
insert into stories (slug,category,chapter_label,title,original_title,original_title_lang,romanised_title,version,version_group,region,characters,est_minutes,release_date,synopsis,body,sort_key,status,publish_at,needs_review,source_url) values ('moonlike-heart-mortal-longing','TALE','CH. IV · TALES','{"en":"Moonlike Heart, Mortal Longing","id":"Hati Laksana Bulan, Kerinduan Fana"}'::jsonb,null,null,null,'3.7','3.X','Mengxuan Vale',array['Rover','Hsin']::text[],null,'2026-09-30','{"en":"The first Tales quest: Xuanqing asks the Rover to help repair a Feeling Capsule meant for Hsin.","id":"Misi Tales pertama: Xuanqing meminta Rover membantu memperbaiki Kapsul Perasaan yang ditujukan untuk Hsin."}'::jsonb,'{"en":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"A message from a stranger introduces Xuanqing and her Myriad Snare, Tuntun. Restoring the broken Feeling Capsule takes the Rover through the Heart of Ruin and Xuanqing''s own memories, ending with a gift delivered to Hsin."}]}]},"id":{"type":"doc","content":[{"type":"paragraph","content":[{"type":"text","text":"Pesan dari orang asing memperkenalkan Xuanqing dan Myriad Snare miliknya, Tuntun. Memulihkan Kapsul Perasaan yang rusak membawa Rover melewati Heart of Ruin dan ingatan Xuanqing sendiri, diakhiri dengan hadiah yang diserahkan kepada Hsin."}]}]}}'::jsonb,6600,'published',null,false,'https://game8.co/games/Wuthering-Waves/archives/624714') on conflict (slug) do update set category=excluded.category,chapter_label=excluded.chapter_label,title=excluded.title,version=excluded.version,version_group=excluded.version_group,region=excluded.region,characters=excluded.characters,synopsis=excluded.synopsis,body=excluded.body,sort_key=excluded.sort_key,status=excluded.status,needs_review=excluded.needs_review,source_url=excluded.source_url;
